package pzvrphysicality;
import java.lang.ref.WeakReference;import java.lang.reflect.Field;import java.util.*;import viewpoint.render.*;import viewpoint.world.ChunkCache;import zombie.characters.IsoPlayer;import zombie.iso.*;

/** Native recipe/install lineage and CONTENTS masks only. This never certifies an item or replaces its own admission checks. */
public final class NativeOwnerVisibility {
 private static final int RECIPES=32,SQUARES=64,CONSUMERS=8;
 private static final class Place {
  final WeakReference<IsoGridSquare> square;final WeakReference<IsoChunk> chunk;final WeakReference<IsoPlayer> actor;final WeakReference<IsoCell> cell;final int x,y,z,wx,wy;
  boolean gathered;WeakReference<ChunkMeshData> data=new WeakReference<>(null);
  Place(IsoGridSquare value,IsoPlayer player){square=new WeakReference<>(value);chunk=new WeakReference<>(value.getChunk());actor=new WeakReference<>(player);cell=new WeakReference<>(player.getCell());x=value.getX();y=value.getY();z=value.getZ();wx=value.getChunk().wx;wy=value.getChunk().wy;}
 }
 private static final Map<Object,Boolean> demands=new WeakHashMap<>();private static final Map<Object,List<Place>> recipes=new WeakHashMap<>();private static final Map<IsoGridSquare,WeakReference<Object>> latest=new WeakHashMap<>();private static volatile boolean requested;private static Field retired;
 public static synchronized boolean request(Object consumer,boolean enabled){if(consumer==null)return false;if(enabled){if(demands.size()>=CONSUMERS&&!demands.containsKey(consumer))return false;demands.put(consumer,Boolean.TRUE);}else demands.remove(consumer);requested=!demands.isEmpty();if(!requested){recipes.clear();latest.clear();}return requested;}
 public static boolean enabled(){return requested;}
 private static IsoPlayer local(){return IsoPlayer.players.length==0?null:IsoPlayer.players[0];}
 public static synchronized boolean watchRecipe(Object recipe,IsoGridSquare square){if(!requested||!Main.ready()||recipe==null||square==null||square.getChunk()==null)return false;var actor=local();if(actor==null||actor.getCell()==null||actor.getCell().getGridSquare(square.getX(),square.getY(),square.getZ())!=square)return false;var places=recipes.get(recipe);if(places==null){if(recipes.size()>=RECIPES)return false;places=new ArrayList<>();recipes.put(recipe,places);}for(var place:places)if(place.square.get()==square)return true;if(places.size()>=SQUARES)return false;places.add(new Place(square,actor));latest.put(square,new WeakReference<>(recipe));return true;}
 public static synchronized void gathered(IsoChunk chunk,int level,Object recipe,boolean completed){if(!requested||recipe==null)return;var places=recipes.get(recipe);if(places==null)return;if(!completed||chunk==null){recipes.remove(recipe);return;}for(var place:places){var square=place.square.get();place.gathered=square!=null&&place.chunk.get()==chunk&&place.z==level&&chunk.wx==place.wx&&chunk.wy==place.wy&&square.getChunk()==chunk&&chunk.getGridSquare(place.x&7,place.y&7,level)==square;}}
 public static synchronized void cooked(Object recipe,ChunkMeshData data,boolean completed){if(!requested||recipe==null)return;var places=recipes.get(recipe);if(places==null)return;for(var place:places)place.data=new WeakReference<>(completed&&place.gathered&&data!=null&&data.level==place.z?data:null);}
 private static boolean alive(ChunkMeshData data){try{if(retired==null){retired=ChunkMeshData.class.getDeclaredField("retired");if(retired.getType()!=boolean.class)return false;retired.setAccessible(true);}return !retired.getBoolean(data);}catch(ReflectiveOperationException|RuntimeException|LinkageError unsupported){return false;}}
 public static synchronized ChunkMeshData committed(Object recipe,IsoGridSquare square){if(!requested||!Main.ready()||recipe==null||square==null)return null;var wanted=latest.get(square);if(wanted==null||wanted.get()!=recipe)return null;var places=recipes.get(recipe);if(places==null)return null;var actor=local();for(var place:places)if(place.square.get()==square){var chunk=place.chunk.get();var cell=place.cell.get();var data=place.data.get();if(!place.gathered||data==null||chunk==null||cell==null||actor==null||place.actor.get()!=actor||actor.getCell()!=cell||cell.getGridSquare(place.x,place.y,place.z)!=square||square.getX()!=place.x||square.getY()!=place.y||square.getZ()!=place.z||square.getChunk()!=chunk||chunk.wx!=place.wx||chunk.wy!=place.wy||chunk.getGridSquare(place.x&7,place.y&7,place.z)!=square||data.level!=place.z||!alive(data)||!ChunkCache.packsOn(square)||ChunkCache.meshOn(square)!=data)return null;return data;}return null;}
 /** Exact pack_model.glsl aRun.z/w bit. Caller must separately prove its own item/source/suppression/current-eye receipt. */
 public static boolean contents(SceneData scene,ChunkMeshData data,IsoGridSquare square){if(!requested||scene==null||data==null||square==null||data.level!=square.getZ()||data.arenaFirst<0||!alive(data)||scene.meshCount<1||scene.meshCount>4096||scene.meshes==null||scene.meshFlags==null||scene.meshFade==null||scene.meshModelSquares==null||scene.meshCount>scene.meshes.length||scene.meshCount>scene.meshFlags.length||scene.meshCount>scene.meshFade.length||scene.meshCount>scene.meshModelSquares.length)return false;int index=-1;for(int at=0;at<scene.meshCount;at++)if(scene.meshes[at]==data){if(index>=0)return false;index=at;}if(index<0||(scene.meshFlags[index]&(SceneData.VISIBLE|SceneData.NEAR))!=(SceneData.VISIBLE|SceneData.NEAR)||!Float.isFinite(scene.meshFade[index])||scene.meshFade[index]<.999f||scene.meshFade[index]>1.001f)return false;int bit=(square.getX()&7)+(square.getY()&7)*8;return (scene.meshModelSquares[index]&(1L<<bit))!=0;}
 /** Original Cook owner/first/count triples and Meshes plan page/first/count ranges, in vertices. */
 public static boolean surface(SceneData scene,ChunkMeshData data,IsoGridSquare square,int kind,int first,int count){
  if(!requested||!Main.ready()||scene==null||data==null||square==null||(kind!=1&&kind!=2)||first<0||count<=0||first%3!=0||count%3!=0||(long)first+count>2_000_000||data.level!=square.getZ()||data.arenaFirst<0||!alive(data)||!ChunkCache.packsOn(square)||ChunkCache.meshOn(square)!=data)return false;
  var actor=local();if(actor==null||actor.getCell()==null||actor.getCell().getGridSquare(square.getX(),square.getY(),square.getZ())!=square)return false;
  if(scene.meshCount<1||scene.meshCount>4096||scene.meshes==null||scene.meshFlags==null||scene.meshFade==null||scene.meshPlan==null||scene.meshPlanLength==null||scene.meshCount>scene.meshes.length||scene.meshCount>scene.meshFlags.length||scene.meshCount>scene.meshFade.length||scene.meshCount>scene.meshPlan.length||scene.meshCount>scene.meshPlanLength.length)return false;
  int index=-1;for(int at=0;at<scene.meshCount;at++)if(scene.meshes[at]==data){if(index>=0)return false;index=at;}
  if(index<0||(scene.meshFlags[index]&5)!=5||!Float.isFinite(scene.meshFade[index])||scene.meshFade[index]<.999f||scene.meshFade[index]>1.001f||data.runs==null||data.runs.length%3!=0||data.runs.length>196608||data.first==null||data.count==null||data.pages==null||data.first.length!=data.count.length||data.first.length!=data.pages.length||data.first.length>4096)return false;
  int owner=(((square.getX()&7)+(square.getY()&7)*8)<<2)|kind,end=first+count,page=-1;
  for(int at=0;at<data.first.length;at++){int lo=data.first[at],size=data.count[at];if(lo<0||size<0||(long)lo+size>2_000_000)return false;if(first>=lo&&end<=lo+size){if(page>=0)return false;page=at;}}
  if(page<0||data.pages[page]==null)return false;int covered=first;
  for(int at=0;at<data.runs.length;at+=3){int own=data.runs[at],lo=data.runs[at+1],size=data.runs[at+2];if(lo<0||size<=0||lo%3!=0||size%3!=0||(long)lo+size>2_000_000)return false;if(lo<end&&lo+size>first){if(own!=owner||lo>covered)return false;covered=Math.max(covered,lo+size);}}
  if(covered<end)return false;int start=scene.meshPlan[index],length=scene.meshPlanLength[index];if(start<0)return length==0;
  if(length<1||scene.plan==null||scene.planEntries<0||scene.planEntries>196608||scene.planEntries>scene.plan.length/3||start>scene.planEntries-length)return false;covered=first;
  // A plan can split a native run. Prove continuous inclusion using only this mesh's selected entries.
  for(int pass=0;pass<length&&covered<end;pass++){int next=covered;for(int entry=start;entry<start+length;entry++){int at=entry*3,p=scene.plan[at],lo=scene.plan[at+1],size=scene.plan[at+2];if(p<0||p>=data.pages.length||lo<0||size<0||(long)lo+size>2_000_000)return false;if(p==page&&lo<=covered&&lo+size>covered)next=Math.max(next,lo+size);}if(next==covered)return false;covered=next;}
  return covered>=end;
 }
 public static synchronized String status(){return "Native owner visibility consumers "+demands.size()+", recipes "+recipes.size()+"; item admission remains caller-owned";}
 private NativeOwnerVisibility(){}
}
